MATCH (c:Country)
WHERE c.continent = 'Asia'
   OR EXISTS {
       MATCH (m:Mountain {name: 'Sickle Moon Peak'})-[:locatedIn]->(c)
   }
RETURN c.name AS country_name

MATCH (c:Country)<-[:flowsThrough]-(r1:River), (c)<-[:flowsThrough]-(r2:River)
WHERE r1.name CONTAINS 'Bolshoy Kunyak' AND r2.name CONTAINS 'Katiss' AND r1 <> r2
RETURN DISTINCT c.name AS country;

MATCH (lake:Lake)
WHERE EXISTS {
    MATCH (lake)<-[:flowsInto]-(r:River)-[:partOf]->(:DrainageBasin {name: 'Ob Basin'})
}
OR EXISTS {
    MATCH (lake)<-[:flowsInto]-(r:River)-[:flowsThrough]->(:Country {name: 'Kazakhstan'})
}
RETURN count(DISTINCT lake) AS count
